package run.ikaros.finance; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/ledgers/{ledgerId}/actions") public class LedgerLifecycleController{private final LedgerLifecycleService service;public LedgerLifecycleController(LedgerLifecycleService s){service=s;}@PostMapping("/archive")public Mono<LedgerView> archive(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.setArchived(a,ledgerId,true);}@PostMapping("/restore")public Mono<LedgerView> restore(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.setArchived(a,ledgerId,false);}}
